-- M10.ReturnStockIn (tenant 1 ONLY): realign backend/page config to match
-- the actual pages the frontend has built (per exact JSON supplied), and
-- switch Unloading to a real two-phase state (UNLOADING_IN_PROGRESS /
-- UNLOADING_COMPLETED via "Start Unloading" / "Finish Unloading"), replacing
-- V288's single UNLOADING_DONE state. Supersedes V288's chain entirely for
-- this workflow; V288's own aria:return-stock-officer page is no longer
-- referenced by any transition (left in place, unused, harmless).
--
-- Final chain:
--   DRAFT -> DISPATCH_QUEUED (aria:dispatch-vehicle-details)
--   DISPATCH_QUEUED -> WEIGHMENT_1 (aria:weighment-capture)
--   WEIGHMENT_1 -> RETURN_STOCK_OFFICER (aria:dispatch-vehicle-details, reused
--       a 2nd time -- the frontend's "Return Stock Officer" screen submits
--       this SAME page again with its Batch/SKU/Qty grid, not a standalone page)
--   RETURN_STOCK_OFFICER -> QC_APPROVED / QC_REJECTED (aria:qc-approval)
--   QC_APPROVED -> UNLOADING_IN_PROGRESS (aria:unloading-progress, "Start Unloading")
--   UNLOADING_IN_PROGRESS -> UNLOADING_COMPLETED (aria:unloading-progress, "Finish Unloading")
--   UNLOADING_COMPLETED -> WEIGHMENT_2 (aria:weighment-capture)
--   WEIGHMENT_2 -> STOCK_CHECKING_OFFICER (aria:stock-checking-officer, its
--       own dedicated page -- NOT a reuse of aria:reconciliation)
--   STOCK_CHECKING_OFFICER -> CLOSED (aria:gate-pass-closure)
--
-- No Loading Allocation, no Manager Weight Approval anywhere in this chain,
-- per explicit requirement -- both remain fully wired for every other
-- workflow, untouched.
--
-- Paired Java changes (same intent, this migration):
--   QcApprovalDecisionListener.QC_PREVIOUS_STATES += "RETURN_STOCK_OFFICER"
--   ReconciliationDecisionListener: M10.ReturnStockIn now reads from
--     "aria:stock-checking-officer" (previousState WEIGHMENT_2), not
--     "aria:reconciliation"/UNLOADING_DONE
--   ReturnStockOfficerItemTransitionListener: PAGE_CODE is
--     aria:dispatch-vehicle-details (reused page), reads "return_stock_items"
--   DispatchInvoiceItemTransitionListener: also accepts
--     "invoice_items_return_stock" (ReturnStockIn's own invoice grid key)
--     alongside "invoice_items" (TankerInbound's)

-- 1. dispatch_vehicle_detail.unloading_supervisor_id: the actual page field
--    is "unloadingSupervisor" (no "Id" suffix) -- V285 only ever mapped
--    "unloadingSupervisorId"/"unloading_supervisor_id", so every real save
--    has been silently dropping this field until now.
UPDATE m0_workflow_projection
SET field_map_json = JSON_MERGE_PATCH(
  field_map_json,
  JSON_OBJECT('unloading_supervisor_id', JSON_ARRAY('unloadingSupervisor', 'unloadingSupervisorId', 'unloading_supervisor_id'))
)
WHERE target_table = 'dispatch_vehicle_detail' AND workflow_code = 'M10.ReturnStockIn'
  AND JSON_CONTAINS_PATH(field_map_json, 'one', '$.unloading_supervisor_id');

-- 2. aria:dispatch-vehicle-details: replace with the actual current page
--    JSON, with ONE safety fix -- "return_stock_items" gained a visibleWhen
--    guard (matching every sibling ReturnStockIn-only field on this same
--    page) since it was missing one in the supplied JSON, which would
--    otherwise show this field on every OTHER flow variant's Dispatch
--    Vehicle Details page too, violating the explicit "don't touch other
--    flow variants" requirement.
UPDATE page_version pv
JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details&size=200"}],"entity":"DispatchVehicleDetail","layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":[{"field":"gpNumber","label":""},{"field":"flowVariantCode"}],"fillLookupEntity":"GatePass","fillLookupField":"gp_number","filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"}],"priorityOverrideField":"priority_override"}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"text","name":"currentUserId","defaultValue":"{{user.username}}","hidden":true},{"kind":"FormField","type":"select","name":"gpNumber","label":"GP Number","required":true,"placeholder":"Select Gate Pass","optionsSource":{"type":"datasource","valueField":"gp_number","labelField":"gp_number","spec":{"type":"entity","entity":"GatePass","select":["id","gp_number","vehicle_no","flow_variant_code","loading_type"],"sort":[{"field":"gp_number","dir":"desc"}]}},"onChangeFill":{"vehicleNo":"vehicle_no","flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"select","name":"unloadingSupervisor","label":"Unloading Supervisor","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"Employee","select":["id","employeename"],"filter":{"and":[{"field":"employeetype","op":"eq","value":"Supervisor"},{"field":"status","op":"eq","value":"A"}]},"sort":[{"field":"employeename","dir":"asc"}]},"valueField":"id","labelField":"employeename"},"placeholder":"Select unloading supervisor","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"RepeatingGroup","name":"return_stock_items","label":"Batch / SKU / Qty / Good & Expiry Stock","minRows":1,"defaultRows":1,"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''","columns":[{"name":"batch_no","label":"Batch No","type":"text","required":true,"width":"1fr","plainBackground":true},{"name":"sku_name","label":"SKU Name","type":"text","required":true,"width":"1.4fr","plainBackground":true},{"name":"qty","label":"Qty","type":"number","required":true,"width":"0.8fr","plainBackground":true},{"name":"good_stock_qty","label":"Good Stock Qty","type":"number","width":"1fr","plainBackground":true},{"name":"expiry_stock_qty","label":"Expiry Stock Qty","type":"number","width":"1fr","plainBackground":true}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add More","action":"repeatingGroup.addRow","color":"secondary"}]},{"kind":"FormField","type":"text","name":"brokerName","label":"Broker Name","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && (#form.flowVariantCode == ''M10.TankerOutbound'' || #form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'')"},{"kind":"FormField","type":"text","name":"brokerContactNumber","label":"Broker Contact Number","pattern":"^[0-9]{10}$","patternError":"Enter a valid 10-digit phone number","maxLength":10,"digitsOnly":true,"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.TankerOutbound''"},{"kind":"FormField","type":"tags","name":"poNumbers","label":"PO Number(s)","required":true,"placeholder":"Type a PO number and press Enter","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.TankerOutbound''"},{"kind":"FormField","type":"file","name":"attachmentDocs","label":"Attachm