true,"width":"0.8fr"}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add Invoice","action":"repeatingGroup.addRow","color":"secondary"}]},{"kind":"FormField","type":"select","name":"oilRmItem","label":"Oil RM Details","multiple":true,"optionsSource":{"type":"datasource","valueField":"sku_code","labelField":["sku_name","product_family"],"searchFields":["sku_code","sku_name","product_family"],"spec":{"type":"entity","entity":"SkuMaster","select":["sku_code","sku_name","product_family"],"filter":{"field":"status","op":"eq","value":"ACTIVE"},"sort":[{"field":"sku_code","dir":"asc"}]}},"placeholder":"Search by SKU code or description","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''"},{"kind":"RepeatingGroup","name":"invoice_items_return_stock","label":"Invoice Details (Return Stock In)","minRows":1,"defaultRows":1,"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''","columns":[{"name":"invoice_no","label":"Invoice No","type":"text","required":true,"width":"1fr"},{"name":"order_id","label":"Order ID","type":"text","required":true,"width":"1fr"},{"name":"rd_code","label":"RD No","type":"text","required":true,"width":"0.8fr"},{"name":"vendor_name","label":"Vendor Name","type":"text","required":true,"width":"1fr"},{"name":"sku_code","label":"SKU","type":"select","required":true,"width":"1.6fr","placeholder":"Search by SKU code or description","optionsSource":{"type":"datasource","valueField":"sku_code","labelField":["sku_code","sku_name"],"labelJoin":" — ","searchFields":["sku_code","sku_name"],"spec":{"type":"entity","entity":"SkuMaster","select":["sku_code","sku_name"],"filter":{"field":"status","op":"eq","value":"ACTIVE"},"sort":[{"field":"sku_code","dir":"asc"}]}}},{"name":"qty","label":"Order Qty","type":"number","required":true,"width":"0.8fr"}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add Invoice","action":"repeatingGroup.addRow","color":"secondary"}]},{"kind":"FormField","type":"select","name":"poVerified","label":"PO Verified","options":["YES","NO - MANAGER APPROVAL"],"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && (#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'')"},{"kind":"FormField","type":"text","name":"poOverrideReason","label":"Reason (if PO not verified)","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && ((#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES'')","requiredWhen":"#form.gpNumber != null && #form.gpNumber != '''' && ((#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES'')"},{"kind":"Grid","name":"returnStockDetailsRow","gap":16,"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''","style":{"gridTemplateColumns":"repeat(auto-fit, minmax(220px, 1fr))"},"children":[{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"Invoice Stock Return Count"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type"}]},{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","placeholder":"Auto-filled after GP Number is selected","optionsSource":{"type":"datasource","valueField":"vehicle_no","labelField":"vehicle_no","spec":{"type":"entity","entity":"GatePass","filter":{"field":"status","op":"eq","value":"GATE_PASS_CREATED"},"select":["id","vehicle_no"],"sort":[{"field":"vehicle_no","dir":"asc"}]}},"onChangeFill":{"loadingType":"loading_type"},"disabled":true},{"kind":"FormField","name":"priority_override","type":"text","readOnly":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Vehicle Movement Type","disabled":true},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","trigger":"page.submitted","variant":"primary","workflowCode":"{{form.flowVariantCode}}","visibleWhen":"#form.gpNumber != null && #form.gpNumber != ''''","args":{"formDataPickKeys":["time_taken"]}}]}]}'
WHERE pd.code = 'aria:dispatch-vehicle-details' AND pv.status = 'PUBLISHED';

-- 3. New page: aria:unloading-progress (buttons wired to a real
--    workflow.transition + explicit targetState so "Finish Unloading"
--    cannot fire before "Start Unloading" actually happened -- the engine
--    only matches a transition whose (currentState, pageCode, targetState)
--    triple exists; QC_APPROVED has no rule targeting UNLOADING_COMPLETED).
INSERT INTO page_definition (tenant_id, code, title, description, category, status, created_at, updated_at)
SELECT -1, 'aria:unloading-progress', 'Unloading Progress',
  'Confirm unloading start and finish for a Return Stock In vehicle, between QC Approval and the second weighment.',
  'M10', 'PUBLISHED', NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id = -1 AND code = 'aria:unloading-progress');

INSERT INTO page_version (page_id, version, status, body_json, created_at)
SELECT pd.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"entity":"GatePass","dataSources":[{"id":"unloadingQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:unloading-progress&size=200"}],"layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"unloadingQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":[{"field":"gpNumber","label":""},{"field":"vehicleNo"}],"fillLookupEntity":"GatePass","fillLookupField":"gp_number","filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"}],"priorityOverrideField":"priority_override"}]},{"kind":"Section","title":"Unloading Progress","fields":[{"kind":"FormField","type":"select","name":"gp_number","label":"GP Number","required":true,"placeholder":"Select Gate Pass","optionsSource":{"type":"datasource","valueField":"gp_number","labelField":"gp_number","spec":{"type":"entity","entity":"GatePass","select":["id","gp_number","vehicle_no","loading_type","workflow_instance_id"],"sort":[{"field":"gp_number","dir":"desc"}]}},"onChangeFill":{"vehicle_no":"vehicle_no","loading_type":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"text","name":"vehicle_no","label":"Vehicle Number","readOnly":true},{"kind":"FormField","name":"priority_override","type":"text","readOnly":true},{"kind":"FormField","type":"text","name":"loading_type","label":"Vehicle Movement Type","readOnly":true}]},{"kind":"Section","title":"Unloading Process / Completion Confirmation","subtitle":"Confirm the unloading start & finish time, then submit.","fields":[{"kind":"FormField","type":"datetime","name":"unloading_start_time","label":"Unloading Start Time"},{"kind":"FormField","type":"datetime","name":"unloading_finish_time","label":"Unloading Finish Time"},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"▶ Start Unloading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"UNLOADING_IN_PROGRESS","color":"primary"},{"kind":"WorkflowActionButton","label":"⏹ Finish Unloading","action":"workflow.transition","instanceId":"{{form.instanceId}}","targetState":"UNLOADING_COMPLETED","color":"secondary"}]}]}]}', NOW()
FROM page_definition pd
WHERE pd.tenant_id = -1 AND pd.code = 'aria:unloading-progress'
  AND NOT EXISTS (SELECT 1 FROM page_version pv WHERE pv.page_id = pd.id);

UPDATE page_definition pd
JOIN page_version pv ON pv.page_id = pd.id AND pv.version = 1
SET pd.current_version_id = pv.id
WHERE pd.tenant_id = -1 AND pd.code = 'aria:unloading-progress' AND pd.current_version_id IS NULL;

-- 4. New page: aria:stock-checking-officer (dedicated page, per the actual
--    build -- not a reuse of aria:reconciliation as V288 assumed).
INSERT INTO page_definition (tenant_id, code, title, description, category, status, created_at, updated_at)
SELECT -1, 'aria:stock-checking-officer', 'Stock Checking Officer',
  'Compare invoice stock against received stock after the second weighment for a Return Stock In vehicle, before gate pass closure.',
  'M10', 'PUBLISHED', NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id = -1 AND code = 'aria:stock-checking-officer');

INSERT INTO page_version (page_id, version, status, body_json, created_at)
SELECT pd.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"stockCheckingQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:stock-checking-officer&size=200"}],"layout":[{"kind":"Grid","columns":12,"gap":16,"children":[{"kind":"Section","title":"Dispatch Queue (Open)","span":12,"fields":[{"kind":"WorkflowQueueList","persona":"StockCheckingOfficer","dataSource":"stockCheckingQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":[{"field":"gpNumber","label":""},"flowVariantCode"],"fillLookupEntity":"GatePass","fillLookupField":"gp_number","filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"}],"priorityOverrideField":"priority_override","fillLookupSpec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"},{"entity":"WeighmentCaptureDetail","as":"wcd","on":"wcd.workflow_instance_id = gate_pass.workflow_instance_id","fields":["wcd.w1_weight_kg as first_weight_kg","wcd.w2_weight_kg as second_weight_kg"]}],"select":["id","gp_number"]}}]},{"kind":"Section","title":"Stock Checking — Invoice vs Received","span":12,"subtitle":"After unloading & the second weighment, compare invoice stock against received stock and record a reason for any difference.","children":[{"kind":"Form","bindings":{"fields":[{"name":"gpNumber","label":"Gate Pass # (scan / pick / type)","type":"select","required":true,"freeSolo":true,"scannable":true,"optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"GatePass","joins":[{"entity":"WorkflowInstance","as":"wi","on":"gate_pass.workflow_instance_id = wi.id"},{"entity":"WeighmentCaptureDetail","as":"wcd","on":"wcd.workflow_instance_id = gate_pass.workflow_instance_id","fields":["wcd.w1_weight_kg as w1WeightKg","wcd.w2_weight_kg as w2WeightKg"]}],"filter":{"and":[{"field":"wi.assigned_role","op":"eq","value":"StockCheckingOfficer"},{"field":"wi.status","op":"eq","value":"OPEN"}]},"select":["id","gp_number"],"sort":[{"field":"gp_number","dir":"desc"}]},"valueField":"gp_number","labelField":"gp_number"},"onChangeFill":{"vehicle_no":"vehicle_no","instanceId":"workflow_instance_id","flow_variant_code":"flow_variant_code","first_weight_kg":"w1WeightKg","second_weight_kg":"w2WeightKg","gatePassId":"id","priority_override":"priority_override","queue_reason":"queue_reason"}},{"name":"queue_reason","label":"Reason for Skipping Priority Vehicle","type":"select","visibleWhen":"#form.priority_override == true","requiredWhen":"#form.priority_override == true","options":[{"label":"Vehicle Already at Weighbridge","value":"VEHICLE_ALREADY_AT_WEIGHBRIDGE"},{"label":"Priority Vehicle Not Ready","value":"PRIORITY_VEHICLE_NOT_READY"},{"label":"Urgent Dispatch Required","value":"URGENT_DISPATCH_REQUIRED"},{"label":"Documents Pending for Priority Vehicle","value":"DOCUMENTS_PENDING"},{"label":"Others","value":"OTHERS"}]},{"name":"queue_reason_other","label":"Please specify the reason","type":"text","visibleWhen":"#form.priority_override == true && #form.queue_reason == ''OTHERS''","requiredWhen":"#form.priority_override == true && #form.queue_reason == ''OTHERS''"},{"name":"vehicle_no","label":"Vehicle","type":"text","readOnly":true},{"name":"priority_override","label":"","type":"text","readOnly":true},{"name":"first_weight_kg","label":"First Weight (kg)","type":"number","readOnly":true},{"name":"second_weight_kg","label":"Second Weight (kg)","type":"number","readOnly":true},{"name":"variance_display_kg","label":"Variance (kg) — auto","type":"number","readOnly":true,"computedFrom":"#form.first_weight_kg - #form.second_weight_kg"},{"name":"variance_reason","label":"Invoice vs Received Stock Difference — Reason","type":"textarea","helperText":"Manual entry: explain any difference between invoiced stock and received stock"}]}},{"kind":"Stack","direction":"row","gap":12,"children":[{"kind":"WorkflowActionButton","label":"✓ Stock Checked — Within Tolerance","action":"workflow.transition","instanceId":"{{form.instanceId}}","color":"primary","submitValues":{"withinTolerance":"YES"}},{"kind":"WorkflowActionButton","label":"⚠ Difference → Manager","action":"workflow.transition","instanceId":"{{form.instanceId}}","color":"error","submitValues":{"withinTolerance":"NO"}}]}]}]}]}', NOW()
FROM page_definition pd
WHERE pd.tenant_id = -1 AND pd.code = 'aria:stock-checking-officer'
  AND NOT EXISTS (SELECT 1 FROM page_version pv WHERE pv.page_id = pd.id);

UPDATE page_definition pd
JOIN page_version pv ON pv.page_id = pd.id AND pv.version = 1
SET pd.current_version_id = pv.id
WHERE pd.tenant_id = -1 AND pd.code = 'aria:stock-checking-officer' AND pd.current_version_id IS NULL;

-- 5. The reorder: M10.ReturnStockIn, tenant 1 only.
UPDATE workflow_definition
SET body_json = '{"code":"M10.ReturnStockIn","version":2,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"DISPATCH_QUEUED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_1","assignedRole":"ReturnStockOfficer"},{"code":"RETURN_STOCK_OFFICER","assignedRole":"QC"},{"code":"QC_APPROVED","assignedRole":"UnloadingSupervisor"},{"code":"QC_REJECTED","terminal":true},{"code":"UNLOADING_IN_PROGRESS","assignedRole":"UnloadingSupervisor"},{"code":"UNLOADING_COMPLETED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_2","assignedRole":"StockCheckingOfficer"},{"code":"STOCK_CHECKING_OFFICER","assignedRole":"FrontGate"},{"code":"CLOSED","terminal":true}],"transitions":[{"from":"DRAFT","to":"DISPATCH_QUEUED","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"DISPATCH_QUEUED","to":"WEIGHMENT_1","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_1","to":"RETURN_STOCK_OFFICER","trigger":"page.submitted","pageCode":"aria:dispatch-vehicle-details"},{"from":"RETURN_STOCK_OFFICER","to":"QC_APPROVED","trigger":"page.submitted","pageCode":"aria:qc-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"RETURN_STOCK_OFFICER","to":"QC_REJECTED","trigger":"page.submitted","pageCode":"aria:qc-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_APPROVED","to":"UNLOADING_IN_PROGRESS","trigger":"page.submitted","pageCode":"aria:unloading-progress","targetState":"UNLOADING_IN_PROGRESS"},{"from":"UNLOADING_IN_PROGRESS","to":"UNLOADING_COMPLETED","trigger":"page.submitted","pageCode":"aria:unloading-progress","targetState":"UNLOADING_COMPLETED"},{"from":"UNLOADING_COMPLETED","to":"WEIGHMENT_2","trigger":"page.submitted","pageCode":"aria:weighment-capture"},{"from":"WEIGHMENT_2","to":"STOCK_CHECKING_OFFICER","trigger":"page.submitted","pageCode":"aria:stock-checking-officer"},{"from":"STOCK_CHECKING_OFFICER","to":"CLOSED","trigger":"page.submitted","pageCode":"aria:gate-pass-closure"}]}'
WHERE code = 'M10.ReturnStockIn' AND status = 'PUBLISHED' AND tenant_id = 1;
